import java.util.List;

class Solution {
    public int countMatches(List<List<String>> items, String ruleKey, String ruleValue) {
        int idx = ruleKey.equals("type") ? 0 : ruleKey.equals("color") ? 1 : 2;
        int count = 0;
        for (List<String> item : items) {
            if (item.get(idx).equals(ruleValue)) count++;
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int countMatches(List<List<String>> items, String ruleKey, String ruleValue) {
        Map<String, Integer> keyToIndex = new HashMap<>();
        keyToIndex.put("type", 0);
        keyToIndex.put("color", 1);
        keyToIndex.put("name", 2);
        int idx = keyToIndex.get(ruleKey);
        int count = 0;
        for (int i = 0; i < items.size(); i++) {
            if (items.get(i).get(idx).equals(ruleValue)) {
                count++;
            }
        }
        return count;
    }
}
